import * as M from './model.mjs';
import {LESSONS,SOURCES} from './lessons.mjs';
import {DATA,backtest} from '../chapter-08/model.mjs';
const CHAPTER=10,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=M.restoreState(localStorage.getItem(M.STORAGE_KEY));}catch{state=M.freshState();}
let step=M.STEPS.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'start';
const $=s=>document.querySelector(s),announce=t=>{$('#announcement').textContent=t;};
function save(){state.done=M.completion(state);try{localStorage.setItem(M.STORAGE_KEY,JSON.stringify(state));$('#save-state').textContent="已儲存在此裝置";}catch{$('#save-state').textContent="無法儲存：離開前請匯出";}progress();}
function progress(){state.done=M.completion(state);const count=Object.values(state.done).filter(Boolean).length;$('#progress').value=count;$('#progress-label').textContent=`${count} / 6項證據步驟 · 學員自評` ;$('#navigation').innerHTML=M.STEPS.map(([id,title,min])=>`<a href="#${id}" ${id===step?'aria-current="step"':''}>${state.done[id]?'✓ ':''}${esc(title)} <small>${min} 分鐘</small></a>`).join('');}
const input=(id,label,type='text')=>`<label class="field" for="${id}">${label}</label><input id="${id}" data-field="${id}" type="${type}" value="${esc(state.fields[id]||'')}">`;
const text=(id,label,cls='')=>`<label class="field" for="${id}">${label}</label><textarea id="${id}" class="${cls}" data-field="${id}">${esc(state.fields[id]||'')}</textarea>`;
const tick=(id,label)=>`<label class="field"><input data-field="${id}" id="${id}" type="checkbox" ${state.fields[id]==='yes'?'checked':''}> ${label}</label>`;
const money=x=>new Intl.NumberFormat('zh-TW',{minimumFractionDigits:4,maximumFractionDigits:4}).format(x),pct=x=>(100*x).toFixed(4)+'%';
function table(run){return `<div class="table-wrap"><table><caption>當前固定計畫 · 合成評估 · 起始NT$1,000</caption><thead><tr><th scope="col">成本／交易名目金額</th><th scope="col">策略最終（NT$）</th><th scope="col">報酬率</th><th scope="col">基準最終（NT$）</th><th scope="col">報酬率</th><th scope="col">策略最大回撤（%）</th><th scope="col">基準最大回撤（%）</th></tr></thead><tbody>${[['10bps',run.base],['30bps',run.sensitivity]].map(([label,r])=>`<tr><th scope="row">${label}</th><td>${money(r.finalWealth)}</td><td>${pct(r.totalReturn)}</td><td>${money(r.benchmarkFinal)}</td><td>${pct(r.benchmarkReturn)}</td><td>${money(r.strategyMaxDrawdown)}</td><td>${money(r.benchmarkMaxDrawdown)}</td></tr>`).join('')}</tbody></table></div><p>最大回撤為正值損失幅度：100×(1−wealth/runningpeak)。納入起始NT$1,000、各區間末資產及最後平倉。只觀察這些邊界，不是區間內或未來虧損上限。成本可能改變成長及回撤；不年化。</p><p>${run.exploratory?"探索性：已在不同計畫下查看評估。":"固定計畫教學評估；此瀏覽器無法確認先前是否看過外部／來源資料。"}</p><details><summary>逐列證據與完整輸入表</summary><p>首個可交易訊號 ${esc(run.base.rows[0].signalDate)}；進場 ${esc(run.base.rows[0].entryDate)}；最後出場 ${esc(run.base.rows.at(-1).exitDate)}。最後平倉成本NT$${money(run.base.finalExitCost)}。下列數值不年化。</p><div class="table-wrap"><table><caption>基本10bps區間紀錄；最後平倉另計</caption><thead><tr><th>訊號</th><th>進場</th><th>出場</th><th>部位</th><th>換手比例</th><th>標的開盤間報酬率</th><th>起始（NT$）</th><th>期末（NT$）</th></tr></thead><tbody>${run.base.rows.map(r=>`<tr><td>${esc(r.signalDate)}</td><td>${esc(r.entryDate)}</td><td>${esc(r.exitDate)}</td><td>${r.position}</td><td>${r.turnover}</td><td>${pct(r.grossReturn)}</td><td>${money(r.startWealth)}</td><td>${money(r.endWealth)}</td></tr>`).join('')}</tbody></table></div><pre>${esc(JSON.stringify(M.EVALUATION_DATA,null,2))}</pre></details>`;}
function plan(){const p=M.currentPlan(state);return text('question',"可測試問題（30字以上），含任何先前評估接觸。")+text('prediction',"本次揭示前的預測（20字以上；若事後回顧須揭露）。")+"<button data-action=\"freeze\">固定不可覆寫的新計畫版本</button>"+`<p>${p?"當前固定版本 "+p.plan.version:"當前輸入沒有有效固定計畫；編輯會使較早結果過期。"}</p><details><summary>全部固定計畫版本（${state.plans.length})</summary>${state.plans.map(p=>`<pre>${esc(JSON.stringify(p,null,2))}</pre>`).join('')}</details>`;}
function results(){const r=M.latestEvidence(state);return "<button data-action=\"run\">揭示／重現兩個預定成本情境</button>"+ (r?table(r)+input('hand',"獨立計算第一列期末資產（NT$，容許誤差.01）。",'number')+"<button data-action=\"hand\">檢查手算</button>":"<p>先固定當前輸入再揭示。舊執行保留於匯出，但不能作當前證據。</p>")+`<details><summary>全部保留評估試驗（${state.runs.length})</summary>${state.runs.map((r,i)=>`<p>執行 ${i+1}，計畫v${r.planVersion}, ${esc(r.time)}: 10bps NT$${money(r.base.finalWealth)}; 30bps NT$${money(r.sensitivity.finalWealth)}${r.exploratory?" · 探索性":''}.</p>`).join('')}</details>`;}
function render(){progress();let extra='';if(step==='start')extra=tick('setup',"我理解獨立路線、合成來源、本機紀錄，以及自評尚未驗證的性質。");if(step==='plan'){if(!state.fields.question&&!state.plans.length){state.fields.question="固定三筆收盤規則，是否改善合成評估區間相對於同期間淨買入持有的觀察取捨？";state.fields.prediction="揭示前我預測較高成本會降低兩者淨結果；若曾先查看，必須在此揭露。";}extra=plan();}if(step==='evidence')extra=results();if(step==='memo')extra=text('memo',"研究備忘錄：1200–1600個中文字，以匯出證據附件支持。",'memo-editor')+`<p id="word-count">${M.wordCount(state.fields.memo||'')}個中文字 · 篇幅不能判定品質</p>`;if(step==='review')extra="<fieldset><legend>關鍵研究誠信條件 — 全部必備</legend>"+M.CRITICAL.map(([id,label])=>tick('critical-'+id,label)).join('')+'</fieldset>'+M.RUBRIC.map(q=>`<div class="record"><h2>${esc(q.title)} (${q.weight}分)</h2><p>${esc(q.anchors)}</p>${input(q.id,"你的自評分數（0–"+q.weight+').','number')}</div>`).join('')+text('reviewNote',"引用規準證據，指出具體弱點或驗證（60字以上）。")+"<button data-action=\"review\">記錄當前初稿自評</button>"+`<p>${state.reviews.length}次自評嘗試保留。分數是學員判斷，不是已驗證成績。</p>`;if(step==='finish')extra=text('revisionNote',"修改正文後，解釋具體修訂、規準與證據（60字以上）。")+"<button data-action=\"revision\">記錄修訂稿與完成檢核</button><button data-action=\"memo-download\" class=\"secondary\">下載當前備忘錄文字</button>"+`<p>${state.revisions.length}次修訂嘗試保留。當前準備狀態：${M.revisionValid(state)?"已記錄自評繳交":"尚未記錄；先檢核當前證據，再修改正文並記錄修訂"}.</p>`;const i=M.STEPS.findIndex(x=>x[0]===step);$('#lesson').innerHTML=`<article>${LESSONS[step]}<div class="panel">${extra}</div><div id="feedback" role="status" aria-live="polite"></div><div class="actions"><button data-action="save">儲存／驗證當前步驟</button>${i?`<a class="button secondary" href="#${M.STEPS[i-1][0]}">返回</a>`:''}${i<5?`<a class="button" href="#${M.STEPS[i+1][0]}">繼續</a>`:''}</div><details><summary>來源與限制</summary><p>原創合成任務／資料；查核日期31 October 2026。本機固定不是外部登錄平台的事前登錄。重複挑選可過度擬合，一段保留資料不能消除。</p>${SOURCES.map(([t,u])=>`<p><a href="${u}">${esc(t)}</a></p>`).join('')}<p><a href="https://www.cos.io/initiatives/prereg">開放科學中心：事前登錄</a></p><p>學習時間、輔助科技與教育效果的真人測試仍待進行。不自動頒發課程證照。</p></details></article>`;}

function feedback(t){$('#feedback').textContent=t;announce(t);}
document.addEventListener('input',e=>{const id=e.target.dataset.field;if(!id)return;if(['question','prediction'].includes(id)){state.fields.integrity='';state.fields.selfReview='';state.fields.hand='';}state.fields[id]=e.target.type==='checkbox'?(e.target.checked?'yes':''):e.target.value;if(id==='memo'&&$('#word-count'))$('#word-count').textContent=M.wordCount(e.target.value)+"個中文字 · 篇幅不能判定品質";save();});
document.addEventListener('click',e=>{if(e.target.closest('a.skip')){e.preventDefault();$('#lesson').focus();return;}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;try{if(action==='privacy')return $('#privacy-dialog').showModal();if(action==='close')return $('#privacy-dialog').close();if(action==='reset'){if(!confirm("只刪除本章本機紀錄？已下載檔案仍保留。"))return;localStorage.removeItem(M.STORAGE_KEY);state=M.freshState();$('#privacy-dialog').close();render();return;}if(action==='export'){const blob=new Blob([JSON.stringify({...state,data:M.EVALUATION_DATA,dataset:M.EVALUATION_ID},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='chapter-10-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}if(action==='review'){const review=M.selfReview(state);save();render();feedback("已記錄自評："+review.score+"/100。修改備忘錄正文，再記錄修訂。分數未經獨立驗證。");return;}if(action==='revision'){M.saveRevision(state);save();render();feedback("已記錄修訂繳交。請匯出完整證據與備忘錄；這是學員自評，不是課程證照。");return;}if(action==='memo-download'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([state.fields.memo||''],{type:'text/plain'}));a.download='capstone-memo.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}if(action==='freeze'){M.freeze(state);save();render();feedback("計畫已固定。須揭露任何先前查看；這不是外部事前登錄。");return;}if(action==='run'){M.evaluate(state);save();render();feedback("已保留兩個預定成本試驗。檢查逐列、手算並替結論加上條件。");return;}if(action==='audit'){const grades=M.auditGrade(state.fields);state.attempts.push({time:new Date().toISOString(),fields:{...state.fields},grades});save();feedback(M.AUDIT.map((q,i)=>`${q.id}: ${grades[i].correct?"正確":"重查 — "+q.hint}`).join(' | '));return;}if(action==='hand'){const r=M.latestEvidence(state);if(!r)throw Error("請先執行當前計畫。");feedback(String(state.fields.hand??'').trim()!==''&&Math.abs(Number(state.fields.hand)-r.base.rows[0].endWealth)<.011?"手算相符。請在備忘錄說明成本與持有區間。":"重查起始 × (1 − 換手比例 × bps/10,000) × 市場因子。讀CSV第一列開盤價，不要套入未來報酬率。");return;}save();feedback(state.done[step]?"已記錄當前步驟證據。文字正確性自行檢核；可匯出供審閱。":"仍缺證據：檢查答案、當前固定輸入、必要說明與條件。完整解答見文字指南。");}catch(error){save();feedback(error.message);}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(M.STEPS.some(x=>x[0]===next)){step=next;render();$('#lesson').focus();}});render();
